// AuthiChain proof-first demo passport — art-QR edition.
// QR art: AI-generated background + real QR module composite (scan-verified with OpenCV before deploy).
const QR_ART = Uint8Array.from(atob(""), c => c.charCodeAt(0));
const QR_BRAND = Uint8Array.from(atob(""), c => c.charCodeAt(0));
const HTML = `<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Product Passport</title>
<style>
:root{
  --ink:#14211b; --cream:#faf7f0; --paper:#ffffff; --gold:#b08d3f; --gold-soft:#d9c391;
  --green:#1d4d3b; --line:#e4ddcc; --mut:#7a7565;
}
*{margin:0;padding:0;box-sizing:border-box}
body{background:var(--cream);color:var(--ink);font-family:ui-sans-serif,system-ui,-apple-system,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;-webkit-font-smoothing:antialiased}
.serif{font-family:Georgia,"Times New Roman",serif}
.wrap{max-width:560px;margin:0 auto;padding:28px 20px 60px}
.step{opacity:0;transform:translateY(14px);animation:rise .7s cubic-bezier(.2,.7,.3,1) forwards}
@keyframes rise{to{opacity:1;transform:none}}
.d1{animation-delay:.2s}.sc1{animation-delay:1.3s}.sc2{animation-delay:2.3s}.sc3{animation-delay:3.3s}.sc4{animation-delay:4.3s}.d5{animation-delay:5.8s}.d6{animation-delay:9.2s}.d8{animation-delay:12.6s}
.eyebrow{font-size:11px;letter-spacing:.22em;text-transform:uppercase;color:var(--mut);margin-bottom:6px}
.card{background:var(--paper);border:1px solid var(--line);border-radius:14px;padding:26px 24px;box-shadow:0 1px 2px rgba(20,33,27,.05),0 12px 32px rgba(20,33,27,.07)}
.brandrow{display:flex;align-items:center;gap:14px}
.mark{width:52px;height:52px;border-radius:50%;background:var(--green);color:#fff;display:flex;align-items:center;justify-content:center;font-size:19px;font-weight:600;letter-spacing:.02em;flex:none}
.brandname{font-size:17px;font-weight:600;line-height:1.25}
.brandsub{font-size:12.5px;color:var(--mut)}
.divider{height:1px;background:var(--line);margin:20px 0}
h1{font-size:26px;line-height:1.2;font-weight:600;letter-spacing:.01em}
.typeline{margin-top:6px;font-size:13.5px;color:var(--mut)}
.kv{display:grid;grid-template-columns:1fr 1fr;gap:14px 18px;margin-top:20px}
.kv .k{font-size:10.5px;letter-spacing:.14em;text-transform:uppercase;color:var(--mut);margin-bottom:3px}
.kv .v{font-size:14.5px;font-weight:500}
.storylabel{margin-top:22px;font-size:10.5px;letter-spacing:.22em;text-transform:uppercase;color:var(--gold)}
.chapter{margin-top:14px;padding-left:14px;border-left:2px solid var(--gold-soft)}
.chapter .ck{font-size:10.5px;letter-spacing:.18em;text-transform:uppercase;color:var(--mut);margin-bottom:3px}
.chapter .ct{font-size:14.5px;line-height:1.62;color:#33302a}
.chapter i, .story i{color:var(--gold);font-style:normal}
.timeline{display:flex;margin-top:24px}
.ms{flex:1;text-align:center;position:relative}
.ms .dot{width:12px;height:12px;border-radius:50%;background:var(--gold);margin:0 auto;animation:pop .5s both;box-shadow:0 0 0 3px #fff,0 0 0 4px var(--gold-soft)}
.ms .lb{font-size:9.5px;letter-spacing:.1em;text-transform:uppercase;color:var(--mut);margin-top:6px;opacity:0;animation:rise .5s both}
.ms1 .dot{animation-delay:1.3s}.ms1 .lb{animation-delay:1.4s}
.ms2 .dot{animation-delay:2.3s}.ms2 .lb{animation-delay:2.4s}
.ms3 .dot{animation-delay:3.3s}.ms3 .lb{animation-delay:3.4s}
.ms4 .dot{animation-delay:4.3s}.ms4 .lb{animation-delay:4.4s}
.ms:not(:last-child)::after{content:"";position:absolute;top:5px;left:calc(50% + 11px);width:calc(100% - 22px);height:2px;background:var(--line)}
@keyframes pop{0%{transform:scale(0)}70%{transform:scale(1.2)}100%{transform:scale(1)}}
.verified{display:flex;align-items:center;gap:14px;padding:16px;border:1px solid var(--line);border-radius:10px;background:#fbf9f3}
.sealsvg{width:44px;height:44px;flex:none;animation:seal .9s 6.4s both}
@keyframes seal{0%{transform:scale(.4);opacity:0}60%{transform:scale(1.12)}100%{transform:scale(1);opacity:1}}
.vt{font-size:14px;font-weight:600}
.vs{font-size:12.5px;color:var(--mut);line-height:1.5;margin-top:2px}
.checks{margin-top:16px;display:flex;flex-direction:column;gap:9px}
.check{display:flex;gap:10px;align-items:center;font-size:13.5px;color:#2a2620}
.tick{width:20px;height:20px;border-radius:50%;background:var(--green);display:flex;align-items:center;justify-content:center;flex:none;animation:pop .5s both}
.tick svg{width:10px;height:10px}
.c1 .tick{animation-delay:6.8s}.c2 .tick{animation-delay:7.6s}.c3 .tick{animation-delay:8.4s}
.check span{opacity:0;animation:rise .5s both}
.c1 span{animation-delay:6.9s}.c2 span{animation-delay:7.7s}.c3 span{animation-delay:8.5s}
.mono{font-family:ui-monospace,SFMono-Regular,Menlo,monospace;font-size:12px;color:var(--mut)}
.share{margin-top:22px;display:flex;align-items:center;gap:14px}
.btn{display:inline-flex;align-items:center;gap:8px;background:var(--green);color:#fff;text-decoration:none;font-size:13.5px;font-weight:600;padding:11px 18px;border-radius:9px}
.qr{width:64px;height:64px;border:1px solid var(--line);border-radius:8px;padding:4px;background:#fff}
.qrart-wrap{text-align:center;margin-top:26px}
.qrart{width:100%;max-width:250px;border-radius:14px;border:1px solid var(--line);box-shadow:0 14px 34px rgba(20,33,27,.14);display:block;margin:0 auto}
.qrart-cap{margin-top:10px;font-size:12.5px;color:var(--mut);line-height:1.5}
.foot{margin-top:34px;text-align:center}
.foot .made{font-size:12px;color:var(--mut)}
.foot a{color:var(--green);font-weight:600;text-decoration:none}
.replay{margin-top:14px;background:none;border:none;color:var(--mut);font-size:12px;text-decoration:underline;cursor:pointer}
.caption{margin-top:14px;text-align:center;font-size:12.5px;color:var(--mut);min-height:16px;opacity:0;animation:rise .5s both}
.cap1{animation-delay:5.2s}.cap2{animation-delay:11.4s}
@media (prefers-reduced-motion:reduce){.step,.tick,.check span,.sealsvg,.caption,.ms .dot,.ms .lb{animation:none!important;opacity:1!important;transform:none!important}}
</style>
</head>
<body>
<div class="wrap">
  <div class="step d1">
    <div class="card">
      <div class="eyebrow" id="eyebrow">Digital product passport</div>
      <div class="brandrow">
        <div class="mark serif" id="mark"></div>
        <div>
          <div class="brandname serif" id="brand"></div>
          <div class="brandsub" id="origin"></div>
        </div>
      </div>
      <div class="divider"></div>
      <h1 class="serif" id="product"></h1>
      <div class="typeline" id="type"></div>
      <div class="kv">
        <div><div class="k">Batch</div><div class="v mono" id="batch"></div></div>
        <div><div class="k">Released</div><div class="v" id="date"></div></div>
        <div><div class="k">Origin</div><div class="v" id="origin2"></div></div>
        <div><div class="k">Proof ID</div><div class="v mono" id="proof"></div></div>
      </div>
      <div class="step sc1 storylabel">The Story</div>
      <div class="step sc1 chapter" id="ch1"><div class="ck" id="ck1"></div><div class="ct" id="ct1"></div></div>
      <div class="step sc2 chapter" id="ch2"><div class="ck" id="ck2"></div><div class="ct" id="ct2"></div></div>
      <div class="step sc3 chapter" id="ch3"><div class="ck" id="ck3"></div><div class="ct" id="ct3"></div></div>
      <div class="step sc4 chapter" id="ch4"><div class="ck" id="ck4"></div><div class="ct" id="ct4"></div></div>
      <div class="timeline">
        <div class="ms ms1"><div class="dot"></div><div class="lb" id="m1">Origin</div></div>
        <div class="ms ms2"><div class="dot"></div><div class="lb" id="m2">Craft</div></div>
        <div class="ms ms3"><div class="dot"></div><div class="lb" id="m3">Release</div></div>
        <div class="ms ms4"><div class="dot"></div><div class="lb" id="m4">Verified</div></div>
      </div>
    </div>
  </div>
  <div class="step d5 caption cap1">This is what a customer sees 1 second after scanning your label.</div>
  <div class="step d5">
    <div class="card">
      <div class="verified">
        <svg class="sealsvg" viewBox="0 0 100 100" fill="none">
          <circle cx="50" cy="50" r="47" stroke="#1d4d3b" stroke-width="3"/>
          <path d="M30 52 L44 66 L71 36" stroke="#1d4d3b" stroke-width="6" stroke-linecap="round" stroke-linejoin="round"/>
        </svg>
        <div>
          <div class="vt">Verified product passport</div>
          <div class="vs">Issued by the brand · independently verifiable</div>
        </div>
      </div>
      <div class="checks">
        <div class="check c1"><span class="tick"><svg viewBox="0 0 12 12"><path d="M2 6.5 L4.8 9 L10 2.5" stroke="#fff" stroke-width="2" fill="none" stroke-linecap="round" stroke-linejoin="round"/></svg></span><span>Signature valid — issued by <b id="vbrand"></b></span></div>
        <div class="check c2"><span class="tick"><svg viewBox="0 0 12 12"><path d="M2 6.5 L4.8 9 L10 2.5" stroke="#fff" stroke-width="2" fill="none" stroke-linecap="round" stroke-linejoin="round"/></svg></span><span>Anchored — record is tamper-evident</span></div>
        <div class="check c3"><span class="tick"><svg viewBox="0 0 12 12"><path d="M2 6.5 L4.8 9 L10 2.5" stroke="#fff" stroke-width="2" fill="none" stroke-linecap="round" stroke-linejoin="round"/></svg></span><span>Shareable — this proof works anywhere</span></div>
      </div>
      <div class="step d6 qrart-wrap">
        <img class="qrart" id="artqr" alt="Branded QR art" onerror="this.parentNode.style.display='none'">
        <div class="qrart-cap">This is what goes on your label — <b>scannable art</b>, unique to the batch.<br>Try it: point your camera at the screen.</div>
      </div>
      <div class="share" style="justify-content:center">
        <a class="btn" id="sharelink" href="#">Share this proof</a>
      </div>
    </div>
  </div>
  <div class="step d8 caption cap2">No app. No login. Works on any phone. — the entire experience is ~45 seconds.</div>
  <div class="step d8 foot">
    <div class="made">This sample passport was made with <a href="https://authichain.com" target="_blank" rel="noopener">AuthiChain</a> — product passports for premium makers.</div>
    <button class="replay" onclick="location.reload()">Replay</button>
  </div>
</div>
<script>
(function(){
  function setText(id, val){
    var el = document.getElementById(id);
    if (!el) { console.error('[passport] missing element #' + id); return false; }
    el.textContent = val;
    return true;
  }
  function setHTML(id, val){
    var el = document.getElementById(id);
    if (!el) { console.error('[passport] missing element #' + id); return false; }
    el.innerHTML = val;
    return true;
  }
  try {
    var q = new URLSearchParams(location.search);
    function esc(s){ var d = document.createElement('div'); d.textContent = s; return d.innerHTML; }
    function em(s){
      var parts = esc(s).split('*');
      var out = parts[0];
      for (var p = 1; p < parts.length; p += 2) {
        out += '<i>' + (parts[p] || '') + '</i>' + (parts[p + 1] || '');
      }
      return out;
    }
    var brand  = q.get('b') || 'Copper & Rye Distilling Co.';
    var product= q.get('p') || 'Huron Reserve — Single Barrel Rye';
    var type   = q.get('t') || 'Small-batch rye whiskey · 750ml';
    var origin = q.get('o') || 'Traverse City, Michigan';
    var date   = q.get('d') || 'October 2026';
    var batch  = q.get('x') || 'HR-14-2026';
    var c1 = q.get('c1'), c2 = q.get('c2'), c3 = q.get('c3'), c4 = q.get('c4');
    var t1 = q.get('s1'), t2 = q.get('s2'), t3 = q.get('s3'), t4 = q.get('s4');
    var fallback = q.get('s');
    var defTitles = ['I — The Field', 'II — The Barrel', 'III — The Hand', 'IV — The Moment'];
    var defTexts = [
      'Michigan rye from a single farm outside Ann Arbor, harvested in the fall of *2021*.',
      'Barrel No. 14, filled *October 2022*. New charred American oak, aged four years through Lake-effect seasons.',
      'Bottled by hand — *212 bottles*, each numbered and signed by the distiller.',
      'Now in your hands. This passport is the proof that this bottle is *exactly* what it claims to be.'
    ];
    var texts = [t1, t2, t3, t4];
    if (fallback) texts[3] = texts[3] || fallback;
    var titles = [c1, c2, c3, c4];
    for (var i = 0; i < 4; i++) {
      setText('ck' + (i+1), titles[i] || defTitles[i]);
      setHTML('ct' + (i+1), em(texts[i] || defTexts[i]));
    }
    var ms = [q.get('m1'), q.get('m2'), q.get('m3'), q.get('m4')];
    var defMs = ['Origin','Craft','Release','Verified'];
    for (var j = 0; j < 4; j++) {
      setText('m' + (j+1), esc(ms[j] || defMs[j]));
    }
    setText('brand', brand);
    setText('vbrand', brand);
    setText('product', product);
    setText('type', type);
    setText('origin', origin);
    setText('origin2', origin);
    setText('date', date);
    setText('batch', batch);
    var initials = brand.replace(/&/g,'and').split(/\s+/).filter(function(w){return /^[A-Za-z]/.test(w)}).slice(0,2).map(function(w){return w[0].toUpperCase()}).join('') || 'AC';
    setText('mark', initials);
    var hex = ''; var seed = brand+product+batch;
    for (var k=0;k<seed.length;k++){ hex += seed.charCodeAt(k).toString(16); if(hex.length>=12) break; }
    while(hex.length<12) hex += '0';
    setText('proof', 'AC-' + hex.slice(0,12).toUpperCase().replace(/(.{4})(.{4})(.{4})/,'$1-$2-$3'));
    var art = document.getElementById('artqr');
    if (art) { art.src = q.get('qr') || '/qr.png'; }
    else { console.error('[passport] missing element #artqr'); }
    var share = document.getElementById('sharelink');
    if (!share) {
      console.error('[passport] missing element #sharelink');
    } else if (navigator.share) {
      share.href = '#';
      share.addEventListener('click', function(e){ e.preventDefault();
        navigator.share({ title: product + ' — verified passport', text: 'Verified product passport for ' + product, url: location.href }).catch(function(){});
      });
    } else {
      share.href = location.href;
      share.addEventListener('click', function(e){ e.preventDefault();
        if (!navigator.clipboard) return;
        navigator.clipboard.writeText(location.href).then(function(){ share.textContent = 'Link copied ✓'; }).catch(function(){});
      });
    }
  } catch (err) {
    console.error('[passport] render failed:', err);
  }
})();
</script>
</body>
</html>
`;
export default {
  async fetch(request) {
    if (request.method !== "GET") return new Response("Method not allowed", { status: 405 });
    const u = new URL(request.url);
    if (u.pathname === "/health") return new Response("ok");
    if (u.pathname === "/qr.png") return new Response(QR_ART, {
      headers: { "content-type": "image/jpeg", "cache-control": "public, max-age=86400" } });
    if (u.pathname === "/authichain-qr.png") return new Response(QR_BRAND, {
      headers: { "content-type": "image/jpeg", "cache-control": "public, max-age=86400" } });
    if (u.pathname !== "/" && u.pathname !== "/passport" && u.pathname !== "/demo")
      return new Response("Not found", { status: 404 });
    return new Response(HTML, {
      headers: { "content-type": "text/html;charset=utf-8", "cache-control": "public, max-age=300" } });
  }
};

